package com.example.minicommerce.shared.domain;import static org.assertj.core.api.Assertions.*;import java.math.BigDecimal;import org.junit.jupiter.api.Test;class MoneyTest{@Test void add_requiresSameCurrency(){assertThatThrownBy(()->new Money(new BigDecimal("1"),"JPY").add(new Money(new BigDecimal("1"),"USD"))).isInstanceOf(IllegalArgumentException.class);}@Test void multiply_usesDecimalMoney(){assertThat(new Money(new BigDecimal("8.00"),"JPY").multiply(3).amount()).isEqualByComparingTo("24.00");}}
